#!/usr/bin/env bash
# Generated by agon-dev-env setup_emulator.py.
set -euo pipefail
export SDL_AUDIODRIVER=dummy

profile_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

# Human launch only after the custodian writes a fresh local checkout.
python3 "${profile_dir}/review_custody.py" check || exit 1
if [[ -z "${DISPLAY:-}" && -z "${WAYLAND_DISPLAY:-}" ]]; then
    echo 'Review not launched: a desktop display is required. Contact Golem.' >&2
    exit 1
fi
if [[ "${SDL_VIDEODRIVER:-}" == dummy ]]; then
    echo 'Review not launched: video is dummy; use the Author desktop. Contact Golem.' >&2
    exit 1
fi
export FLEXE_UART_OBSERVER_OUTPUT="${profile_dir}/last-run/sender-progress.jsonl"
if [[ -e "$FLEXE_UART_OBSERVER_OUTPUT" ]]; then
    echo "Observer output exists; preserve this profile and stop" >&2
    exit 1
fi
fab_bin="$(readlink -f "${profile_dir}/flexe-agon-emulator.bin")"
sdl_lib="${HOME}/.local/lib"

if [[ -f "${sdl_lib}/libSDL3.so.0" ]]; then
    export LD_LIBRARY_PATH="${sdl_lib}${LD_LIBRARY_PATH:+:${LD_LIBRARY_PATH}}"
fi
export SDL_VIDEODRIVER="${SDL_VIDEODRIVER:-${WAYLAND_DISPLAY:+wayland}}"
export SDL_VIDEODRIVER="${SDL_VIDEODRIVER:-x11}"

cd "${profile_dir}"
if ! sha256sum --check --status .mos-release.sha256; then
    printf 'Profile MOS does not match %s: %s\n' \
        "$(< .mos-release)" "${profile_dir}" >&2
    exit 1
fi


if [[ ! -f .bespoke-vdp-profile ]]; then
    echo 'Missing bespoke profile marker; refusing stock fallback' >&2
    exit 1
fi
sha256sum --check --status .runtime.sha256 || {
    echo 'Rally-28 throughput runtime identity mismatch; redeploy the active candidate' >&2
    exit 1
}
for arg in "$@"; do
    case "$arg" in
        --vdp*|--mos*|--sdcard*|--firmware*)
            echo 'Runtime overrides are forbidden in the Rally-28 throughput review profile' >&2
            exit 1 ;;
    esac
done

if [[ ! -f "${profile_dir}/.bespoke-vdp-profile" ]]; then
    exec "${fab_bin}" \
        --firmware platform \
        --mos "${profile_dir}/mos_platform.bin" \
        --sdcard "${profile_dir}/sdcard" \
        "$@"
fi



rm -f -- "$profile_dir/sdcard/rally25/replies.log" "$profile_dir/sdcard/rally25/ticks.log" "$profile_dir/sdcard/rally25/prt.log" "$profile_dir/sdcard/rally25/clock.log" "$profile_dir/sdcard/rally25/failure.log"
export AGON_FLEXE_FIRMWARE="$profile_dir/esp32-firmware.bin"
export AGON_FLEXE_ELF="$profile_dir/esp32-firmware.elf"
export AGON_FLEXE_ENGINE=jit
export AGON_FLEXE_ARTIFACTS="$profile_dir/last-run"
mkdir -p "$AGON_FLEXE_ARTIFACTS"

vdp_name="$(< "${profile_dir}/.bespoke-vdp-profile")"
if [[ "${vdp_name}" != "$(basename "${vdp_name}")" ]]; then
    printf 'Invalid bespoke VDP module name: %s\n' "${vdp_name}" >&2
    exit 1
fi
for profile_input in \
    flexe-agon-emulator.bin mos_platform.bin mos_platform.map \
    "${vdp_name}" sdcard; do
    if [[ ! -e "${profile_dir}/${profile_input}" ]]; then
        printf 'Missing bespoke emulator input: %s\n' \
            "${profile_dir}/${profile_input}" >&2
        exit 1
    fi
done

run_root="$(mktemp -d "${TMPDIR:-/tmp}/fab-bespoke.XXXXXX")"
trap 'rmdir -- "${run_root}"' EXIT
(
    cd "${run_root}"
    "${fab_bin}" \
        --renderer sw \
        --firmware platform \
        --mos "${profile_dir}/mos_platform.bin" \
        --vdp "${profile_dir}/${vdp_name}" \
        --sdcard "${profile_dir}/sdcard" \
        -z "$@"
)
